module beautiful_sequence(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] a,  // count of 0s\n    input [7:0] b,  // count of 1s\n    input [7:0] c,  // count of 2s\n    input [7:0] d,  // count of 3s\n    output reg [7:0] seq_out [0:31],  // output sequence\n    output reg [5:0] seq_len,          // sequence length\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE   = 2'd0;\n    localparam [1:0] START  = 2'd1;\n    localparam [1:0] CONSTRUCT = 2'd2;\n    localparam [1:0] FINISH = 2'd3;\n    reg [1:0] state, next_state;\n    \n    // Internal registers\n    reg [7:0] counts [0:3];\n    reg [7:0] temp_counts [0:3];\n    reg [2:0] current_num;\n    reg [2:0] next_num;\n    reg [5:0] idx;\n    reg [2:0] attempts;\n    reg [15:0] cycle_count;\n    localparam [15:0] MAX_CYCLES = 16'd500;\n    reg found_valid;\n    \n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            done <= 1'b0;\n            seq_len <= 6'd0;\n            idx <= 6'd0;\n            cycle_count <= 16'd0;\n            attempts <= 3'd0;\n            current_num <= 3'd0;\n            next_num <= 3'd0;\n            found_valid <= 1'b0;\n            \n            // Initialize arrays\n            for (i = 0; i < 4; i = i+1) begin\n                counts[i] <= 8'd0;\n                temp_counts[i] <= 8'd0;\n            end\n            for (i = 0; i < 32; i = i+1) begin\n                seq_out[i] <= 8'd0;\n            end\n        end else begin\n            cycle_count <= cycle_count + 16'd1;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= START;\n                        // Initialize counts\n                        counts[0] <= a;\n                        counts[1] <= b;\n                        counts[2] <= c;\n                        counts[3] <= d;\n                        attempts <= 3'd0;\n                        seq_len <= 6'd0;\n                        found_valid <= 1'b0;\n                        cycle_count <= 16'd0;\n                    end\n                end\n                \n                START: begin\n                    if (attempts < 3'd4) begin\n                        if (counts[attempts] == 8'd0) begin\n                            attempts <= attempts + 3'd1;\n                        end else begin\n                            // Copy counts to temp\n                            for (i = 0; i < 4; i = i+1) begin\n                                temp_counts[i] <= counts[i];\n                            end\n                            temp_counts[attempts] <= counts[attempts] - 8'd1;\n                            current_num <= attempts[2:0];\n                            seq_out[0] <= attempts[2:0];\n                            idx <= 6'd1;\n                            state <= CONSTRUCT;\n                        end\n                    end else begin\n                        // All attempts exhausted\n                        state <= FINISH;\n                    end\n                end\n                \n                CONSTRUCT: begin\n                    if (cycle_count >= MAX_CYCLES) begin\n                        state <= START;\n                        attempts <= attempts + 3'd1;\n                    end else if (idx < 6'd32) begin\n                        case (current_num)\n                            3'd0: begin\n                                // 0 can only be followed by no number\n                                state <= START;\n                                attempts <= attempts + 3'd1;\n                            end\n                            \n                            3'd1: begin\n                                if (temp_counts[2] > 8'd0) begin\n                                    next_num <= 3'd2;\n                                    temp_counts[2] <= temp_counts[2] - 8'd1;\n                                    seq_out[idx] <= 3'd2;\n                                    idx <= idx + 6'd1;\n                                    current_num <= 3'd2;\n                                end else begin\n                                    state <= START;\n                                    attempts <= attempts + 3'd1;\n                                end\n                            end\n                            \n                            3'd2: begin\n                                if (temp_counts[1] > 8'd0) begin\n                                    next_num <= 3'd1;\n                                    temp_counts[1] <= temp_counts[1] - 8'd1;\n                                    seq_out[idx] <= 3'd1;\n                                    idx <= idx + 6'd1;\n                                    current_num <= 3'd1;\n                                end else if (temp_counts[3] > 8'd0) begin\n                                    next_num <= 3'd3;\n                                    temp_counts[3] <= temp_counts[3] - 8'd1;\n                                    seq_out[idx] <= 3'd3;\n                                    idx <= idx + 6'd1;\n                                    current_num <= 3'd3;\n                                end else begin\n                                    state <= START;\n                                    attempts <= attempts + 3'd1;\n                                end\n                            end\n                            \n                            3'd3: begin\n                                // 3 can only be followed by 2\n                                if (temp_counts[2] > 8'd0) begin\n                                    next_num <= 3'd2;\n                                    temp_counts[2] <= temp_counts[2] - 8'd1;\n                                    seq_out[idx] <= 3'd2;\n                                    idx <= idx + 6'd1;\n                                    current_num <= 3'd2;\n                                end else begin\n                                    state <= START;\n                                    attempts <= attempts + 3'd1;\n                                end\n                            end\n                            \n                            default: begin\n                                state <= START;\n                                attempts <= attempts + 3'd1;\n                            end\n                        endcase\n                        \n                        // Check if all counts are zero\n                        if (temp_counts[0] == 8'd0 && temp_counts[1] == 8'd0 && \n                            temp_counts[2] == 8'd0 && temp_counts[3] == 8'd0) begin\n                            seq_len <= idx;\n                            found_valid <= 1'b1;\n                            state <= FINISH;\n                        end\n                    end else begin\n                        // Reached max sequence length\n                        state <= FINISH;\n                        seq_len <= idx;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule